-- script 662
Update ServiceHeader Set    cashreceived = a.cashreceived From   ( SELECT dbo.serviceheader.serviceinvcode , cashreceived =    Round (  Round (
       Round(Sum ((dbo.servicedetail.price * qty )* ( 1 - dbo.servicedetail.discperc * .01) ) , 2)      * (1 - dbo.serviceheader.discperc /100) ,  2) - flatdisc + misccharges , 0 ) FROM dbo.serviceheader,dbo.servicedetail   WHERE  dbo.serviceheader.serviceinvcode = dbo.servicedetail.serviceinvcode AND       dbo.serviceheader.posted = 'Y' AND dbo.serviceheader.servicecatcode In (10 , 12) GROUP BY dbo.serviceheader.serviceinvcode, dbo.serviceheader.discperc, dbo.serviceheader.flatdisc, dbo.serviceheader.misccharges) a

Where ServiceHeader.ServiceInvcode = a.ServiceInvcode
GO

