-- script 1345
update prledger  set invtotal=PR.nettotal  From    (SELECT   prinvcode = prledger.prinvcode,         nettotal=ROUND(     SUM((prdetail.looseqty + prdetail.bonusqty) * prdetail.unitsalestax) +     SUM(ROUND(prdetail.looseqty * prdetail.prprice *       (1 - (.01 * prdetail.discperc)) * prdetail.gstperc * .01, 2)) +     ROUND((SUM((prdetail.looseqty * prdetail.prprice) *       (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) -      prledger.flatdisc) * (prledger.invgstperc1 * .01), 2), 0)     + ROUND(SUM((prdetail.looseqty * prdetail.prprice) *       (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) +       prledger.misccharges + prledger.salestax - prledger.flatdisc, 0)       FROM     prledger,        prdetail     WHERE    prledger.prinvcode = prdetail.prinvcode   GROUP BY prledger.prinvcode,      prledger.suppcode,       prledger.prcatcode,      prledger.date,      prledger.discperc,      prledger.misccharges,      prledger.salestax,      prledger.flatdisc,     prledger.invgstperc1  ) as PR        where prledger.prinvcode=PR.prinvcode
GO

-- script 1346
update purledger  set invtotal=p.net  from     (SELECT  purinvcode=purledger.purinvcode,        Net=ROUND(     SUM((purdetail.looseqty + purdetail.packqty + purdetail.bonusqty) *      purdetail.unitsalestax) +     SUM(ROUND((purdetail.looseqty + purdetail.packqty) * purdetail.purprice *       (1 - (.01 * purdetail.discperc)) * purdetail.gstperc * .01, 2)) +     ROUND((SUM(((purdetail.looseqty + purdetail.packqty) * purdetail.purprice) *       (1 - (.01 * purdetail.discperc))) *       (1- (.01 * purledger.discperc)) - purledger.flatdisc) *       (purledger.invgstperc1 * .01), 2), 0) + ROUND(SUM((purdetail.looseqty + purdetail.packqty) * purdetail.purprice *       (1 - (.01 * purdetail.discperc))) * (1- (.01 * purledger.discperc)) +       purledger.misccharges + purledger.salestax - purledger.flatdisc, 0)   FROM     purledger,       purdetail   WHERE           purledger.purinvcode = purdetail.purinvcode    GROUP BY purledger.purinvcode,     purledger.suppcode,      purledger.purcatcode,     purledger.postdate,     purledger.discperc,     purledger.misccharges,     purledger.salestax,     purledger.flatdisc,     purledger.InvGSTPerc1    ) as P      where purledger.purinvcode=p.purinvcode
GO

