-- script 1401
update srdetail set saleprice=saleprice/(case packunits when 0 then 1 else packunits end ) where srinvcode in (select srinvcode from srledger where saleinvcode is null)
GO

-- script 1403
update srledger  set invtotal= A.invtotal    from srledger,     (    select   srinvcode=srledger.srinvcode,    Invtotal=ROUND(     SUM( (srdetail.looseqty + srdetail.bonusqty) * srdetail.unitsalestax) +      SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *          (1 - (.01 * srdetail.discperc)) * srdetail.gstperc * .01, 2)) +     ROUND( (sum( (srdetail.looseqty * srdetail.srprice) *         (1 - (.01 * srdetail.discperc))) *          (1- (.01 * srledger.discperc)) - srledger.flatdisc) *          (srledger.invgstperc1 * .01), 2), 0) +       Round( sum( (srdetail.looseqty * srdetail.srprice) *         (1 - (.01 * srdetail.discperc))) *          (1- (.01 * srledger.discperc)) + srledger.misccharges +          srledger.salestax - srledger.flatdisc, 0)    from srledger,srdetail  where srledger.srinvcode=srdetail.srinvcode     AND     srledger.posted = 'Y'    GROUP BY srledger.srinvcode,     srledger.custcode,      srledger.srcatcode,     srledger.date,     srledger.discperc,     srledger.misccharges,     srledger.salestax,     srledger.flatdisc,     srledger.invgstperc1,     srledger.salesmancode,     srledger.saleinvcode    ) as A    where  srledger.srinvcode=A.srinvcode
