DECLARE @dbname VarChar(150)  DECLARE @dbcount INT    Select @dbcount = count(*)   From master..Sysdatabases  Where lower(name) like '%databasev%'    IF @dbcount > 0    Begin   Declare db_cursor SCROLL Cursor For     Select name     From master..Sysdatabases    Where lower(name) like '%databasev%'    order by name   FOR Read Only    OPEN db_cursor     Fetch Last From db_cursor   INTO @dbname      IF @@Fetch_Status <> 0     Select @dbname = name FROM master..Sysdatabases Where lower(name) like '%database%'   CLOSE db_cursor   DEALLOCATE db_cursor   END    ELSE   Select @dbname = name FROM master..Sysdatabases Where lower(name) like '%database%'      BEGIN TRANSACTION                DECLARE @JobID BINARY(16)      DECLARE @ReturnCode INT        SELECT @ReturnCode = 0       IF (SELECT COUNT(*) FROM msdb.dbo.syscategories WHERE name = N'[Uncategorized (Local)]') < 1     EXECUTE msdb.dbo.sp_add_category @name = N'[Uncategorized (Local)]'     SELECT @JobID = job_id         FROM   msdb.dbo.sysjobs        WHERE (name = N'TSQL_Job_StockLedger')           IF (@JobID IS NOT NULL)        BEGIN      IF (EXISTS (SELECT  *                 FROM    msdb.dbo.sysjobservers                 WHERE   (job_id = @JobID) AND (server_id <> 0)))     BEGIN       RAISERROR (N'Unable to import job ''TSQL_Job_StockLedger'' since there is already a multi-server job with this name.', 16, 1)       GOTO QuitWithRollback      END     ELSE       EXECUTE msdb.dbo.sp_delete_job @job_name = N'TSQL_Job_StockLedger'       SELECT @JobID = NULL    END     BEGIN      EXECUTE @ReturnCode = msdb.dbo.sp_add_job @job_id = @JobID OUTPUT , @job_name = N'TSQL_Job_StockLedger', @owner_login_name = N'sa', @description = N'No description available.', @category_name = N'[Uncategorized (Local)]', @enabled = 1, @notify_level_email = 0, @notify_level_page = 0, @notify_level_netsend = 0, @notify_level_eventlog = 2, @delete_level= 0    IF (@@ERROR <> 0 OR @ReturnCode <> 0) GOTO QuitWithRollback      EXECUTE @ReturnCode = msdb.dbo.sp_add_jobstep @job_id = @JobID, @step_id = 1, @step_name = N'TSQL_Job_StockLedgerStep 1', @command = N'EXEC SP_StockLedger', @database_name = @dbname, @server = N'', @database_user_name = N'', @subsystem = N'TSQL', @cmdexec_success_code = 0, @flags = 0, @retry_attempts = 0, @retry_interval = 0, @output_file_name = N'', @on_success_step_id = 0, @on_success_action = 1, @on_fail_step_id = 0, @on_fail_action = 2    IF (@@ERROR <> 0 OR @ReturnCode <> 0) GOTO QuitWithRollback     EXECUTE @ReturnCode = msdb.dbo.sp_update_job @job_id = @JobID, @start_step_id = 1       IF (@@ERROR <> 0 OR @ReturnCode <> 0) GOTO QuitWithRollback      EXECUTE @ReturnCode = msdb.dbo.sp_add_jobschedule @job_id = @JobID, @name = N'TSQL_Job_StockLedgerSchedule 1', @enabled = 1, @freq_type = 4, @active_start_date = 20030904, @active_start_time = 0, @freq_interval = 1, @freq_subday_type = 8, @freq_subday_interval = 2, @freq_relative_interval = 0, @freq_recurrence_factor = 1, @active_end_date = 99991231, @active_end_time = 235959    IF (@@ERROR <> 0 OR @ReturnCode <> 0) GOTO QuitWithRollback      EXECUTE @ReturnCode = msdb.dbo.sp_add_jobserver @job_id = @JobID, @server_name = N'(local)'     IF (@@ERROR <> 0 OR @ReturnCode <> 0) GOTO QuitWithRollback     END  COMMIT TRANSACTION            GOTO   EndSave                QuitWithRollback:    IF (@@TRANCOUNT > 0) ROLLBACK TRANSACTION   EndSave:
