-- script 1830
DECLARE @OldSuppCode INT  DECLARE @SuppCode INT  DECLARE @OldIcode int  DECLARE @Icode int  DECLARE @Counter INT  DECLARE @ConflictRows INT    UPDATE ItemSuppliers  SET  Priority=1  WHERE Icode IN (SELECT Icode FROM itemsuppliers    GROUP BY Icode,priority HAVING COUNT(*) > 1)       DECLARE C1 CURSOR FOR    SELECT ICode, SuppCode FROM Itemsuppliers    WHERE Icode IN   (SELECT Icode FROM itemsuppliers   GROUP BY Icode,priority HAVING COUNT(*) > 1)   ORDER BY Icode, SuppCode      OPEN C1        SELECT @Counter=1     FETCH NEXT FROM C1 INTO @OldICode, @OldSuppCode     WHILE @@FETCH_STATUS = 0   BEGIN    FETCH NEXT FROM C1 INTO @ICode, @SuppCode      IF (@OldICode=@Icode AND @OldSuppCode<>@SuppCode)      BEGIN      UPDATE ItemSuppliers      SET Priority=@Counter + 1      WHERE Icode=@Icode AND SuppCode=@SuppCode            SELECT @Counter=@Counter + 1     END    ELSE     BEGIN      SELECT @Counter=1     END      SELECT @OldIcode=@Icode    SELECT @OldSuppCode=@SuppCode       END   CLOSE C1   DEALLOCATE C1
GO

