-- script 1871
Update SRDetail
Set SRDetail.SaleRowId = sd.RowId
From  SRLedger srl, SaleDetail sd
Where srl.saleinvcode = sd.saleinvcode AND
   	   srl.srinvcode = SRDetail.srinvcode AND
	   sd.icode = SRDetail.icode AND
	   sd.batch = SRDetail.batch AND
	   sd.expiry = SRDetail.expiry
GO

