-- script 1876
Update DueSatisfyDetail
Set DueSatisfyDetail.SaleRowId = sd.RowId
From  DueSatisfyHeader dsh, SaleDetail sd
Where dsh.saleinvcode = sd.saleinvcode AND
   	   dsh.duesatisfycode = DueSatisfyDetail.duesatisfycode AND
	   sd.icode = DueSatisfyDetail.icode AND
	   sd.gcode = DueSatisfyDetail.gcode AND
	   sd.due In ('S' , 'D' , 'X')
GO

