-- script 2248
Declare @pk_constraint VarChar(50)
Declare @sql VarChar(100)
Set NoCount ON	
Select @pk_constraint = Cast ( self.Name As VarChar(50) )
From SysObjects self , SysObjects parent 
Where self.xtype = 'PK' and self.parent_obj = parent.id and Lower(parent.name) = 'duedeletedetail'
Set @sql = 'Alter Table DueDeleteDetail Drop Constraint ' + @pk_constraint
IF Not (@pk_constraint Is Null Or @pk_constraint = '' ) Execute (@sql)
Set NoCount OFF
GO

