-- script 2285
DECLARE @catcount int, @min_vochatcode int, @max_vochcatcode int, @i int
DECLARE @const VARCHAR(200), @SQL VARCHAR(4000)

SET @catcount = 0
SET @catcount = (SELECT ISNULL( (SELECT COUNT(VochCatCode) FROM VocherCategory WHERE VochCatCode >= 18 AND VochCatCode< = 100) ,0))
IF @catcount > 0 
BEGIN
	SET @max_vochcatcode = 0
	SET @max_vochcatcode = (SELECT MAX(A)
							FROM (SELECT A=ISNULL((SELECT MAX(VochCatCode) + 1 FROM VocherCategory), 0)
							UNION SELECT A=101) T)

	SELECT @const = (Select const_name=Cast(c.name As VarChar(200)) 
					From 
						(SELECT * FROM sysobjects where name = 'vochercategory') vc,
						SysObjects c, 
						SysObjects m, 
						sysforeignkeys f,
						syscolumns sc
					Where 
						c.xtype = 'F' and 
						c.parent_obj = m.id and 
						Lower(m.name) = 'VocherCategoryDetail' and 
						c.id = f.constid and 
						f.rkeyid = vc.id and
						sc.id = f.fkeyid and
						f.fkey = sc.colid)

	SET @SQL = 'ALTER TABLE VocherCategoryDetail DROP CONSTRAINT ' + @const
	IF NOT (@const IS NULL OR @const = '')
	BEGIN
		EXECUTE (@SQL)
	END

	SELECT @const = (Select const_name=Cast(c.name As VarChar(200))
					From 
						(SELECT * FROM sysobjects where name = 'vochercategory') vc,
						SysObjects c, 
						SysObjects m, 
						sysforeignkeys f,
						syscolumns sc
					Where 
						c.xtype = 'F' and 
						c.parent_obj = m.id and 
						Lower(m.name) = 'VocherCategoryHeader' and 
						c.id = f.constid and 
						f.rkeyid = vc.id and
						sc.id = f.fkeyid and
						f.fkey = sc.colid)

	SET @SQL = 'ALTER TABLE VocherCategoryHeader DROP CONSTRAINT ' + @const
	IF NOT (@const IS NULL OR @const = '')
	BEGIN
		EXECUTE (@SQL)
	END

	SELECT @const = (Select const_name=Cast(c.name As VarChar(200))
					From 
						(SELECT * FROM sysobjects where name = 'vochercategory') vc,
						SysObjects c, 
						SysObjects m, 
						sysforeignkeys f,
						syscolumns sc
					Where 
						c.xtype = 'F' and 
						c.parent_obj = m.id and 
						Lower(m.name) = 'GroupVoucherCategory' and 
						c.id = f.constid and 
						f.rkeyid = vc.id and
						sc.id = f.fkeyid and
						f.fkey = sc.colid)

	SET @SQL = 'ALTER TABLE GroupVoucherCategory DROP CONSTRAINT ' + @const
	IF NOT (@const IS NULL OR @const = '')
	BEGIN
		EXECUTE (@SQL)
	END

	SELECT @const =	(Select const_name=Cast(c.name As VarChar(200))
					From 
						(SELECT * FROM sysobjects where name = 'vochercategory') vc,
						SysObjects c, 
						SysObjects m, 
						sysforeignkeys f,
						syscolumns sc
					Where 
						c.xtype = 'F' and 
						c.parent_obj = m.id and 
						Lower(m.name) = 'GLHeader' and 
						c.id = f.constid and 
						f.rkeyid = vc.id and
						sc.id = f.fkeyid and
						f.fkey = sc.colid)

	SET @SQL = 'ALTER TABLE GLHeader DROP CONSTRAINT ' + @const
	IF NOT (@const IS NULL OR @const = '')
	BEGIN
		EXECUTE (@SQL)
	END

	SET @i = 0
	WHILE @i < @catcount
	BEGIN
		SET @min_vochatcode = (SELECT MIN(VochCatCode) FROM VocherCategory WHERE VochCatCode >= 18 AND VochCatCode< = 100)

		UPDATE GroupVoucherCategory SET VochCatCode = @max_vochcatcode WHERE VochCatCode = @min_vochatcode
		UPDATE GLHeader SET VochCatCode = @max_vochcatcode WHERE VochCatCode = @min_vochatcode
		UPDATE VocherCategoryDetail SET VochCatCode = @max_vochcatcode WHERE VochCatCode = @min_vochatcode
		UPDATE VocherCategoryHeader SET VochCatCode = @max_vochcatcode WHERE VochCatCode = @min_vochatcode
		UPDATE VocherCategory SET VochCatCode = @max_vochcatcode WHERE VochCatCode = @min_vochatcode

		SET @max_vochcatcode = @max_vochcatcode + 1
		SET @i = @i + 1
	END

	UPDATE _tabmaxkey 
	SET Tabmaxkey = @max_vochcatcode
	WHERE TABNAME = 'vochercategory'

	-- BUILD CONSTRAINTS HERE
	ALTER TABLE VocherCategoryDetail
	ADD CONSTRAINT FK_VocherCategory_VocherCategoryDetail 
	FOREIGN KEY (VochCatCode) References VocherCategory (VochCatCode)

	ALTER TABLE VocherCategoryHeader
	ADD CONSTRAINT FK_VocherCategory_VocherCategoryHeader
	FOREIGN KEY (VochCatCode) References VocherCategory (VochCatCode)

	ALTER TABLE GroupVoucherCategory
	ADD CONSTRAINT FK_GroupVoucherCategory_VocherCategory
	FOREIGN KEY (VochCatCode) References VocherCategory (VochCatCode)

	ALTER TABLE GLHeader
	ADD CONSTRAINT FK_VocherCategory_GLHeader
	FOREIGN KEY (VochCatCode) References VocherCategory (VochCatCode)

END
GO

