-- script 3046
SELECT 
	POPOLICYCODE=WK.WEEKDAYCODE,
	WEEKDAYCODE=WK.WEEKDAYCODE,
	WEEKOFMONTH=WM.WEEKOFMONTH
FROM
	(SELECT weekdaycode=1 UNION ALL
	SELECT weekdaycode=2 UNION ALL
	SELECT weekdaycode=3 UNION ALL
	SELECT weekdaycode=4 UNION ALL
	SELECT weekdaycode=5 UNION ALL
	SELECT weekdaycode=6 UNION ALL
	SELECT weekdaycode=7) WK,
	(SELECT weekofmonth=1 UNION ALL 
	SELECT weekofmonth=2 UNION ALL 
	SELECT weekofmonth=3 UNION ALL 
	SELECT weekofmonth=4 UNION ALL 
	SELECT weekofmonth=5) WM
GO

