-- script 5625
DELETE StudentClass
FROM
	(SELECT CS.StudentCode, CS.ClassCode
	FROM 
		StudentClass CS, 
		(SELECT SC.StudentCode, AdmissionDate=MAX(SC.AdmissionDate)
		FROM StudentClass SC, Class C
		WHERE SC.ClassCode =C.ClassCode AND C.Active='Y'
		GROUP BY StudentCode
		HAVING COUNT(SC.ClassCode) > 1) T
	WHERE CS.StudentCode = T.StudentCode AND CS.AdmissionDate=T.AdmissionDate) M
WHERE StudentClass.StudentCode=M.StudentCode AND StudentClass.ClassCode <> M.ClassCode
GO

