-- script 5637
UPDATE Student
SET CurrentClass = 
	(SELECT CL.ClassCode
	FROM Class CL 
	WHERE ClassCode IN 
		(SELECT SC.ClassCode
		FROM StudentClass SC, Class C 
		WHERE SC.StudentCode=Student.StudentCode AND C.ClassCode = SC.ClassCode AND C.Active='Y' AND
			SC.AdmissionDate IN 
				(SELECT AdmissionDate=MAX(S.AdmissionDate) 
				FROM StudentClass S
				WHERE SC.StudentCode = S.StudentCode)))
GO

